/**
 * Unit tests for JacksonAnnotationIntrospector.findNameForSerialization
 */
public class JacksonAnnotationIntrospector_findNameForSerialization_TriageGen0Test {

    private JacksonAnnotationIntrospector introspector;
    private Annotated mockAnnotated;

    @Before
    public void setUp() {
        // We use a spy or a subclass if we need to mock protected _findAnnotation and _hasAnnotation
        // However, since we want to test the logic of the method itself, we must mock the behavior 
        // of the internal helper methods. Because they are protected, we can use a Mockito spy.
        introspector = Mockito.spy(new JacksonAnnotationIntrospector());
        mockAnnotated = Mockito.mock(Annotated.class);
    }

    @Test
    public void testFindNameWithJsonGetter() {
        JsonGetter mockGetter = Mockito.mock(JsonGetter.class);
        when(mockGetter.value()).thenReturn("getterName");

        // Mock _findAnnotation(a, JsonGetter.class) -> mockGetter
        // Mock _findAnnotation(a, JsonProperty.class) -> null
        // Mock _hasAnnotation(...) -> false
        doReturn(mockGetter).when(introspector)._findAnnotation(mockAnnotated, JsonGetter.class);
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonProperty.class);

        PropertyName result = introspector.findNameForSerialization(mockAnnotated);

        assertEquals("getterName", result.getName());
    }

    @Test
    public void testFindNameWithJsonProperty() {
        JsonGetter mockGetter = null;
        JsonProperty mockProperty = Mockito.mock(JsonProperty.class);
        when(mockProperty.value()).thenReturn("propertyName");

        doReturn(mockGetter).when(introspector)._findAnnotation(mockAnnotated, JsonGetter.class);
        doReturn(mockProperty).when(introspector)._findAnnotation(mockAnnotated, JsonProperty.class);

        PropertyName result = introspector.findNameForSerialization(mockAnnotated);

        assertEquals("propertyName", result.getName());
    }

    @Test
    public void testFindNameWithJsonSerialize() {
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonGetter.class);
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonProperty.class);
        // Simulate _hasAnnotation(a, JsonSerialize.class) returning true
        doReturn(true).when(introspector)._hasAnnotation(mockAnnotated, JsonSerialize.class);

        PropertyName result = introspector.findNameForSerialization(mockAnnotated);

        assertEquals("", result.getName());
    }

    @Test
    public void testFindNameWithJsonView() {
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonGetter.class);
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonProperty.class);
        doReturn(false).when(introspector)._hasAnnotation(mockAnnotated, JsonSerialize.class);
        doReturn(true).when(introspector)._hasAnnotation(mockAnnotated, JsonView.class);

        PropertyName result = introspector.findNameForSerialization(mockAnnotated);

        assertEquals("", result.getName());
    }

    @Test
    public void testFindNameWithJsonRawValue() {
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonGetter.class);
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonProperty.class);
        doReturn(false).when(introspector)._hasAnnotation(mockAnnotated, JsonSerialize.class);
        doReturn(false).when(introspector)._hasAnnotation(mockAnnotated, JsonView.class);
        doReturn(true).when(introspector)._hasAnnotation(mockAnnotated, JsonRawValue.class);

        PropertyName result = introspector.findNameForSerialization(mockAnnotated);

        assertEquals("", result.getName());
    }

    @Test
    public void testFindNameReturnsNullWhenNoAnnotationsMatch() {
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonGetter.class);
        doReturn(null).when(introspector)._findAnnotation(mockAnnotated, JsonProperty.class);
        doReturn(false).when(introspector)._hasAnnotation(mockAnnotated, JsonSerialize.class);
        doReturn(false).when(introspector)._hasAnnotation(mockAnnotated, JsonView.class);
        doReturn(false).when(introspector)._hasAnnotation(mockAnnotated, JsonRawValue.class);

        PropertyName result = introspector.findNameForSerialization(mockAnnotated);

        assertNull(result);
    }
}
